-- Curated 00AI NOTE templates: task-specific content and working database packages.
ALTER TABLE templates ADD COLUMN audience TEXT NOT NULL DEFAULT 'team';
ALTER TABLE templates ADD COLUMN tags_json TEXT NOT NULL DEFAULT '[]';
ALTER TABLE templates ADD COLUMN difficulty TEXT NOT NULL DEFAULT '쉬움';
ALTER TABLE templates ADD COLUMN setup_minutes INTEGER NOT NULL DEFAULT 5;
ALTER TABLE templates ADD COLUMN featured INTEGER NOT NULL DEFAULT 0 CHECK(featured IN (0,1));
ALTER TABLE templates ADD COLUMN database_json TEXT NOT NULL DEFAULT '{}';
ALTER TABLE template_versions ADD COLUMN database_json TEXT NOT NULL DEFAULT '{}';
ALTER TABLE template_versions ADD COLUMN audience TEXT NOT NULL DEFAULT 'team';
ALTER TABLE template_versions ADD COLUMN tags_json TEXT NOT NULL DEFAULT '[]';
ALTER TABLE template_versions ADD COLUMN difficulty TEXT NOT NULL DEFAULT '쉬움';
ALTER TABLE template_versions ADD COLUMN setup_minutes INTEGER NOT NULL DEFAULT 5;
ALTER TABLE template_versions ADD COLUMN featured INTEGER NOT NULL DEFAULT 0 CHECK(featured IN (0,1));
CREATE INDEX IF NOT EXISTS templates_audience_featured ON templates(audience,featured,visibility,review_status);
UPDATE templates SET audience=CASE WHEN category IN ('정책기획','사업관리','성과관리','청년공간 운영') THEN 'public' ELSE 'team' END, tags_json=CASE WHEN category LIKE '%회의%' THEN '["회의록","결정사항"]' WHEN category LIKE '%정책%' THEN '["정책검토","근거자료"]' ELSE '["업무관리","협업"]' END, difficulty='쉬움', setup_minutes=5, featured=CASE WHEN id IN ('public-meeting-minutes','public-project-brief','public-policy-brief','public-policy-review','public-handover','public-request-tracker','public-outcome-review') THEN 1 ELSE 0 END WHERE owner_id IS NULL;
